/// Generated by capgen from fixture.cap: whether one Envelope fits every bound inside it.
/// Input: the value. Output: true when it fits.
fn fits_envelope(value: &Envelope) -> bool {
    self::fits_reply(&value.reply)
        && value.tags.len() <= crate::LIST_ITEMS_MAX
        && value
            .tags
            .iter()
            .all(|item0| item0.len() <= crate::TEXT_BYTES_MAX)
        && value.extra.as_ref().is_none_or(self::fits_header)
        && value.grid.len() <= crate::LIST_ITEMS_MAX
        && value.grid.iter().all(|item0| {
            item0.len() <= crate::LIST_ITEMS_MAX
                && item0
                    .iter()
                    .all(|item1| item1.len() <= crate::TEXT_BYTES_MAX)
        })
}

/// Generated by capgen from fixture.cap: whether one Header fits every bound inside it.
/// Input: the value. Output: true when it fits.
fn fits_header(value: &Header) -> bool {
    value.name.len() <= crate::TEXT_BYTES_MAX && value.value.len() <= crate::TEXT_BYTES_MAX
}

/// Generated by capgen from fixture.cap: whether one Reply fits every bound inside it.
/// Input: the value. Output: true when it fits.
fn fits_reply(value: &Reply) -> bool {
    value.body.len() <= crate::BYTES_MAX
}

/// Generated by capgen from fixture.cap: whether one Keyed fits every bound inside it.
/// Input: the value. Output: true when it fits.
fn fits_keyed(value: &Keyed) -> bool {
    value.label.len() <= crate::TEXT_BYTES_MAX
}

/// Generated by capgen from fixture.cap: whether one Request fits every bound inside it.
/// Input: the value. Output: true when it fits.
fn fits_request(value: &Request) -> bool {
    value.url.len() <= crate::TEXT_BYTES_MAX
        && value.headers.len() <= crate::LIST_ITEMS_MAX
        && value.headers.iter().all(self::fits_header)
        && value
            .body
            .as_ref()
            .is_none_or(|item0| item0.len() <= crate::BYTES_MAX)
}

